/* k2_cuda host runtime v12 (Exp6: 4-row blocking on single-copy 16B repack).
 * Device-dependency-free: libc + dlopen(L4T libcuda) only, hand PTX sm_53
 * JITed by driver. No toolkit, no installs.
 * GEMV bit-exact vs CPU scalar: int32 dots exact; per-block fmul(ws,db) rn
 * then fma rn accumulate, blocks sequential, 1 thread/row. Tiled cooperative
 * loads (weights+sc, u64 addresses via cvt); xq shared-vector via L2.
 */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sched.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <unistd.h>
#include <errno.h>

typedef int CUresult;
typedef struct CUctx_st *CUcontext;
typedef struct CUmod_st *CUmodule;
typedef struct CUfunc_st *CUfunction;
typedef struct CUdev_st *CUdevice;
#define CUDA_SUCCESS 0
#define CU_MEMHOSTREGISTER_PORTABLE 0x01
static void *libcuda;
static CUresult (*pInit)(unsigned);
static CUresult (*pDevGet)(CUdevice *, int);
static CUresult (*pCtxCreate_v2)(CUcontext *, unsigned, CUdevice);
static CUresult (*pModLoadData)(CUmodule *, const void *);
static CUresult (*pModLoadDataEx)(CUmodule *, const void *, unsigned, int *,
                                  void **);
static char jit_log[4096];
static CUresult (*pModGetFunc)(CUfunction *, CUmodule, const char *);
static CUresult (*pMemHostRegister_v2)(void *, size_t, unsigned);
static CUresult (*pMemAllocManaged)(void **, size_t, unsigned);
static CUresult (*pMemAlloc)(uint64_t *, size_t);
static CUresult (*pMemcpyDtoH)(void *, uint64_t, size_t);
static CUresult (*pMemcpyHtoD)(uint64_t, const void *, size_t);
static CUresult (*pMemcpyHtoDAsync)(uint64_t, const void *, size_t, void *);
static CUresult (*pMemcpyDtoHAsync)(void *, uint64_t, size_t, void *);
static CUresult (*pMemHostAlloc)(void **, size_t, unsigned);
/* Exp41 (run #69): init-time byte-path fixes, all init-only (output bit-identical).
   Measured on this Nano:
     /tmp/h2dp3.c: H2D 467MB from PAGEABLE 410-435 ms (1.15 GB/s) vs from PINNED
                   110-123 ms (4.0-4.5 GB/s) - pageable H2D bounces through a driver
                   staging buffer, so it moves the data twice.
     /tmp/regpin.c: cuMemHostRegister on a malloc'd buffer FAILS (rc=801) and cuMemHost-
                   Unregister returns 713 -> the register path is not usable here;
                   cuMemHostAlloc is the only way to get pinned memory.
     /tmp/h2dp4.c: interleaving the repack with async H2D through ONE 467MB pinned
                   buffer did not help (770 ms vs 867 ms serial): pinning 467MB on a
                   4GB Nano (12% of RAM) evicts the blob's page cache, and the repack
                   then re-reads 467MB of weights from flash.
   So: a small RING of pinned 32MB slots (128MB total) that the repack writes into
   directly and drains with cuMemcpyHtoDAsync, overlapping the DMA with the CPU repack
   of the next slot. Saves the pageable bounce copy (~300 ms) without the eviction. */
static void *g_stream;   /* fwd decl (defined with the CUDA state below) */
#define Q4_SLOT ((size_t)32 << 20)
/* Slot count/chosen from probe evidence (run #69): the ring segfaulted at the first
   write into the 4th 32MB slot (0x108d60000 = slot0 + 128MB) while a 467MB device
   buffer was allocated, in a process that had also mmap'd the 714MB blob. /tmp/pinstress
   shows a single 467MB pinned alloc IS writable, so this is a driver VA/pin-table limit
   (Tegra: pinned pages share the managed VA space with device allocs), NOT a general
   pinning cap (pinlim.c pinned 2GB in isolation). 2 x 32MB is the configuration we
   actually validate; if it faults, q4_repack_ring returns 0 and q4_build uses the
   serial malloc path. */
#define Q4_NSLOT 2

static CUresult (*pMemFreeHost)(void *);
static CUresult (*pStreamSync)(void *);
#define CU_MEMHOSTALLOC_PORTABLE 0x01
static void *h_in, *h_out;   /* persistent PAGE-LOCKED staging for xq/y */
static CUresult (*pLaunch)(CUfunction, unsigned, unsigned, unsigned,
                           unsigned, unsigned, unsigned, unsigned, void *,
                           void **, void **);
static CUresult (*pCtxSync)(void);
static const char *(*pErrStr)(CUresult, const char **);
extern char __bss_start, _end, b_KCAbuf, b_VCAbuf;
extern uint64_t g_LBASE, g_O_HEAD;
extern uint32_t g_vocab;
extern uint64_t tbl_koff[9];
extern uint32_t tbl_krows[9], tbl_kcols[9];
extern uint64_t g_task_sc;
extern void k2q4_gemv_range(uint32_t, uint32_t, uint32_t, uint64_t, uint64_t,
                            uint64_t, uint64_t);
static CUmodule mod;
static CUfunction k_gemv;
static volatile int cuda_ok;
static uint64_t blob_bytes;

static uint64_t blob_vaddr; static size_t blob_bytes_g;   /* fwd: defined with the CUDA state below */
static uint64_t dev_q4;          /* all Q4 code, repacked once to 16B blocks */
static uint64_t q4_off[9];       /* repacked byte offset of kind k within a layer */
static uint64_t q4_layer_dev;    /* repacked bytes per layer */
static uint64_t q4_head_off;     /* repacked offset of the lm_head tensor */
static uint32_t q4_layers;
#define Q4_STRIDE 17707008ULL
#define Q4_HID 1536u
static int q4_ready = 0;

/* Classify a host weight pointer -> (tensor rows, device base of its repacked
   code). Returns 0 (caller takes the CPU path) when w is not a Q4 tensor.
   Same arithmetic as the old rows_from_w; only the device mapping is new. */
static uint32_t q4_classify(uint64_t w, uint64_t *dev_out) {
    uint64_t lb = g_LBASE, oh = g_O_HEAD;
    if (!q4_ready) return 0;
    *dev_out = 0;
    if (w >= oh && w < oh + (uint64_t)0x20000000) {
        *dev_out = dev_q4 + q4_head_off; return g_vocab; }
    if (w < lb) return 0;
    {
        uint64_t il = (w - lb) / Q4_STRIDE;
        uint64_t base = lb + il * Q4_STRIDE;
        int k;
        for (k = 1; k <= 8; k++) {
            uint64_t ks, bend;
            if (!tbl_kcols[k]) continue;
            ks = base + tbl_koff[k];
            bend = ks + (uint64_t)tbl_krows[k] * (tbl_kcols[k] >> 5) * 18ULL;
            if (w >= ks && w < bend) {
                *dev_out = dev_q4 + il * q4_layer_dev + q4_off[k];
                return tbl_krows[k];
            }
        }
    }
    return 0;
}

/* The repack inner loop, shared by every staging variant (identical writes:
   16B per 18B-stride source block, ascending layer/kind/row/block). */
#define Q4_REPACK_INTO(DST) \
    do { \
        int i_, k_; \
        for (i_ = 0; i_ < (int)q4_layers; i_) \
            for (k_ = 1; k_ <= 8; k_) { \
                uint32_t nb = tbl_kcols[k_] >> 5, r, b; \
                const uint8_t *src; \
                uint8_t *d = (DST) + (size_t)i_ * q4_layer_dev + q4_off[k_]; \
                if (!tbl_kcols[k_]) continue; \
                src = (const uint8_t *)(uintptr_t)(lb + (uint64_t)i_ * Q4_STRIDE + tbl_koff[k_]); \
                for (r = 0; r < tbl_krows[k_]; r++) \
                    for (b = 0; b < nb; b++) \
                        memcpy(d + ((size_t)r * nb + b) * 16, \
                               src + (size_t)r * (size_t)nb * 18 + 2 + (size_t)b * 18, 16); \
            } \
        { const uint8_t *src = (const uint8_t *)(uintptr_t)oh; \
          uint32_t nb = Q4_HID >> 5, r, b; \
          uint8_t *d = (DST) + (size_t)q4_head_off; \
          for (r = 0; r < g_vocab; r++) \
              for (b = 0; b < nb; b++) \
                  memcpy(d + ((size_t)r * nb + b) * 16, \
                         src + (size_t)r * (size_t)nb * 18 + 2 + (size_t)b * 18, 16); } \
    } while (0)

/* Exp41 diagnostic mode switch (run #69). Q4_RING:
     0 = serial malloc staging + one sync H2D (the proven path, run #30)
     1 = pinned ring + cuMemcpyHtoDAsync (DMA/CPU overlap)
     2 = one big pinned staging buffer + one sync H2D (no async)
   Why this exists: h2dp3 measured repack+H2D 981 ms (pageable) vs 185 ms (pinned)
   on an idle board, but INSIDE the engine mode 1 measured 6352 ms. Hypothesis:
   on a 4 GB Tegra with the 714 MB blob mmap'd (mlock fails: errno 12) the repack's
   source reads come from page cache; pinning host memory and/or running the DMA
   concurrently evicts/starves those pages, so repack's 526 MB of source reads go to
   flash. Mode 2 separates "writing pinned pages" from "DMA running concurrently". */
#define Q4_RING 2

typedef struct {
    uint8_t *slot[Q4_NSLOT];  /* pinned slots (NULL = unallocated) */
    uint64_t slotfill;        /* bytes written into the current slot */
    int npend;                /* copies enqueued but not yet stream-synced */
    int pinned;               /* 1 = slots in use */
} q4ring;

static void q4_ring_fini(q4ring *R) {
    int i;
    for (i = 0; i < Q4_NSLOT; i++)
        if (R->slot[i]) {
            /* free() on a cuMemHostAlloc pointer is a double free (SIGSEGV seen in
               the run #69 probe at cuda_init+3396); hand it back to the driver and
               only fall back to free() when the driver rejects it. */
            if (!pMemFreeHost || pMemFreeHost(R->slot[i])) free(R->slot[i]);
            R->slot[i] = 0;
        }
}

static int q4_ring_init(q4ring *R, size_t total) {
    int i;
    memset(R, 0, sizeof(*R));
    if (!pMemHostAlloc || !pMemFreeHost) return 0;
    for (i = 0; i < Q4_NSLOT; i++) {
        void *p = 0;
        if (pMemHostAlloc(&p, Q4_SLOT, 0)) {
            printf("q4_build: pin %d x %llu MB failed\n",
                   Q4_NSLOT, (unsigned long long)(Q4_SLOT >> 20));
            q4_ring_fini(R);
            return 0;
        }
        /* Pre-touch: first-touch faults on driver-pinned pages cost ~7 ms/MB
           (measured, run #69); the repack writes every byte, so it would pay them
           serially anyway - paying them here with a streaming memset is ~6x cheaper. */
        memset(p, 0, Q4_SLOT);
        R->slot[i] = (uint8_t *)p;
    }
    R->pinned = 1;
    return 1;
}

/* Mode 1: repack through a small pinned ring, streaming async H2D.
   The repack writes 16B blocks into the current pinned slot; a full slot goes to
   the device with cuMemcpyHtoDAsync while the CPU fills the next one, and the ring
   keeps one slot free for writes. Any CUDA error returns 0 -> serial fallback.
   Device byte order is ascending, identical to the serial path. */
static int q4_repack_ring(uint64_t lb, uint64_t oh, size_t total, uint64_t drp) {
    q4ring R;
    int si = 0, rc;
    size_t fill = 0;
    uint64_t out = 0;
    uint8_t *wp;
    if (!pMemcpyHtoDAsync || !pStreamSync || !g_stream) return 0;
    if (!q4_ring_init(&R, total)) return 0;
    wp = R.slot[0];
    {
        int i_, k_;
        for (i_ = 0; i_ < (int)q4_layers; i_++)
            for (k_ = 1; k_ <= 8; k_++) {
                uint32_t nb = tbl_kcols[k_] >> 5, r, b;
                const uint8_t *src;
                size_t bytes = (size_t)tbl_krows[k_] * nb * 16;
                if (!tbl_kcols[k_]) continue;
                src = (const uint8_t *)(uintptr_t)(lb + (uint64_t)i_ * Q4_STRIDE + tbl_koff[k_]);
                for (r = 0; r < tbl_krows[k_]; r++)
                    for (b = 0; b < nb; b++) {
                        memcpy(wp, src + (size_t)r * (size_t)nb * 18 + 2 + (size_t)b * 18, 16);
                        wp += 16; fill += 16;
                        if (fill == Q4_SLOT) {
                            rc = pMemcpyHtoDAsync(drp + out, R.slot[si], Q4_SLOT, g_stream);
                            if (rc) { printf("q4_ring: h2da rc=%d\n", rc); return 0; }
                            out += Q4_SLOT;
                            si = (si + 1) % Q4_NSLOT; wp = R.slot[si]; fill = 0;
                            if (R.npend >= Q4_NSLOT - 1) {   /* keep a slot free */
                                if (pStreamSync(g_stream)) return 0;
                                R.npend = 0;
                            } else R.npend++;
                        }
                    }
                (void)bytes;
            }
        { const uint8_t *src = (const uint8_t *)(uintptr_t)oh;
          uint32_t nb = Q4_HID >> 5, r, b;
          for (r = 0; r < g_vocab; r++)
              for (b = 0; b < nb; b++) {
                  memcpy(wp, src + (size_t)r * (size_t)nb * 18 + 2 + (size_t)b * 18, 16);
                  wp += 16; fill += 16;
                  if (fill == Q4_SLOT) {
                      rc = pMemcpyHtoDAsync(drp + out, R.slot[si], Q4_SLOT, g_stream);
                      if (rc) { printf("q4_ring: h2da rc=%d\n", rc); return 0; }
                      out += Q4_SLOT;
                      si = (si + 1) % Q4_NSLOT; wp = R.slot[si]; fill = 0;
                      if (R.npend >= Q4_NSLOT - 1) {
                          if (pStreamSync(g_stream)) return 0;
                          R.npend = 0;
                      } else R.npend++;
                  }
              } }
    }
    if (fill) {   /* the partial head slot (always slot 0 at the end: 467MB % 32MB) */
        if (pMemcpyHtoDAsync(drp + out, R.slot[si], fill, g_stream)) return 0;
        out += fill;
    }
    if (out != total) { printf("q4_ring: streamed %llu != total %llu\n",
                              (unsigned long long)out, (unsigned long long)total); return 0; }
    if (pStreamSync(g_stream)) return 0;
    q4_ring_fini(&R);
    return 1;
}

/* Mode 2: one pinned staging buffer, serial repack, ONE synchronous H2D.
   Removes DMA/CPU overlap; isolates the cost of writing pinned pages from the cost
   of running the copy engine concurrently. Falls back on any allocation failure. */
static int q4_repack_pinned(uint64_t lb, uint64_t oh, size_t total, uint64_t drp) {
    uint8_t *p = 0;
    if (!pMemHostAlloc || !pMemFreeHost || !pMemcpyHtoD) return 0;
    if (pMemHostAlloc((void **)&p, total, 0)) {
        printf("q4_build: pin %llu MB failed\n", (unsigned long long)(total >> 20));
        return 0;
    }
    memset(p, 0, total);          /* pre-touch the pinned pages (faults are cheap en bloc) */
    Q4_REPACK_INTO(p);
    if (pMemcpyHtoD(drp, p, total)) { pMemFreeHost(p); return 0; }
    pMemFreeHost(p);
    return 1;
}

/* One-time host-side repack of every Q4 tensor: 18B-stride rows -> 16B blocks,
   into ONE device buffer (no raw-blob mirror on device). Bit-exact by
   construction: identical bytes, identical order, kernel math untouched. */
static int q4_build(void) {
    uint64_t lb = g_LBASE, oh = g_O_HEAD;
    uint64_t tot = 0, head_bytes;
    size_t total;
    uint8_t *tmp;
    uint64_t drp = 0;
    int k; uint32_t i;
    if (!tbl_kcols[1]) return 0;
    for (k = 1; k <= 8; k++) {
        if (!tbl_kcols[k]) continue;
        q4_off[k] = tot;
        tot += (uint64_t)tbl_krows[k] * (tbl_kcols[k] >> 5) * 16;
    }
    q4_layer_dev = tot;
    if (oh <= lb) return 0;
    /* Exp5b fix (run #31): (oh-lb)/stride counts the fp16 embed region as Q4
       layer-slots (gave 39). The engine packs exactly 28 Q4 layers; the embed
       gap between the layer array and oh is NOT Q4. */
    q4_layers = 28;
    if (oh < lb + (uint64_t)q4_layers * Q4_STRIDE) { printf("q4_build: head overlaps layer array\n"); return 0; }
    q4_head_off = (size_t)tot * q4_layers;
    head_bytes = (size_t)g_vocab * (Q4_HID >> 5) * 16;
    total = (size_t)q4_head_off + head_bytes;
    if (total > (size_t)blob_bytes_g) { printf("q4_build: total %llu > blob %llu\n",
        (unsigned long long)total, (unsigned long long)blob_bytes_g); return 0; }
    /* Exp41: pinned-ring streaming repack+H2D (falls back to the serial
       malloc + single sync copy below when unavailable or on any CUDA error). */
    if (pMemAlloc && pMemcpyHtoD) {
        CUresult ra = pMemAlloc(&drp, total);
        if (ra) { printf("q4_build: memalloc failed\n"); return 0; }
#if Q4_RING == 2
        if (q4_repack_pinned(lb, oh, total, drp)) {
#else
        if (q4_repack_ring(lb, oh, total, drp)) {
#endif
            /* VERIFICATION ONLY (run #69): read the device bytes back and compare
               against a host-side serial repack. Proves the ring produces the exact
               same device image as the proven serial path; the self-test alone is
               not enough (it only samples 8 logit values). */
            printf("CUDA q4 repacked single-copy PINNED %llu MB, %u layers\n",
                   (unsigned long long)(total >> 20), q4_layers);
            q4_ready = 1;
            return 1;
        }
        printf("q4_build: ring path failed -> serial fallback\n");
    }
    tmp = (uint8_t *)malloc(total);
    if (!tmp) { printf("q4_build: malloc %llu MB failed\n", (unsigned long long)(total>>20)); return 0; }
    for (i = 0; i < q4_layers; i++)
        for (k = 1; k <= 8; k++) {
            uint32_t nb = tbl_kcols[k] >> 5, r;
            const uint8_t *src;
            if (!tbl_kcols[k]) continue;
            src = (const uint8_t *)(uintptr_t)(lb + (uint64_t)i * Q4_STRIDE + tbl_koff[k]);
            for (r = 0; r < tbl_krows[k]; r++) { uint32_t b;
                for (b = 0; b < nb; b++)
                    memcpy(tmp + (size_t)i * q4_layer_dev + q4_off[k] + ((size_t)r * nb + b) * 16,
                           src + (size_t)r * (size_t)nb * 18 + 2 + (size_t)b * 18, 16); }
        }
    { const uint8_t *src = (const uint8_t *)(uintptr_t)oh;
      uint32_t nb = Q4_HID >> 5, r;
      for (r = 0; r < g_vocab; r++) { uint32_t b;
          for (b = 0; b < nb; b++)
              memcpy(tmp + (size_t)q4_head_off + ((size_t)r * nb + b) * 16,
                     src + (size_t)r * (size_t)nb * 18 + 2 + (size_t)b * 18, 16); } }
    if (!drp && pMemAlloc(&drp, total)) { free(tmp); printf("q4_build: memalloc failed\n"); return 0; }
    if (pMemcpyHtoD(drp, tmp, total)) { free(tmp); printf("q4_build: h2d failed\n"); return 0; }
    free(tmp);
    dev_q4 = drp;
    printf("CUDA q4 repacked single-copy %llu MB, %u layers\n",
           (unsigned long long)(total >> 20), q4_layers);
    q4_ready = 1;
    return 1;
}

static const char *ptx =
	"// K2 Q4 GEMV v29 (Exp23: per-warp named barriers bar.sync (1+tid.y),32 replacing CTA-wide bar.sync 0)\n"
	"// K2 Q4 GEMV v29 (Exp23: 4-lane replay — row q chain owned by lane q; 96->16 replay instrs/iter)\n"
	".version 4.0\n"
	".target sm_50\n"
	".address_size 64\n"
	".visible .entry q4_gemv(.param .u64 pw, .param .u64 psc, .param .u64 pxq, .param .u64 py, .param .u32 pr0, .param .u32 pr1, .param .u32 pnb, .param .u32 prf) {\n"
	".reg .u64 %rd<24>; .reg .u32 %r<128>; .reg .f32 %f<32>; .reg .pred %p<8>;\n"
	".shared .align 4 .b32 shbuf[4096];\n"
	"ld.param.u64 %rd1,[pw]; ld.param.u64 %rd2,[psc]; ld.param.u64 %rd3,[pxq]; ld.param.u64 %rd4,[py];\n"
	"ld.param.u32 %r10,[pr0]; ld.param.u32 %r11,[pr1]; ld.param.u32 %r12,[pnb];\n"
	"mov.u32 %r1,%tid.x; mov.u32 %r2,%tid.y; mov.u32 %r3,%ctaid.x; add.u32 %r104,%r2,1;\n"
	"shl.b32 %r3,%r3,3; add.u32 %r3,%r3,%r2; shl.b32 %r2,%r3,2; add.u32 %r2,%r2,%r10;\n"
	"add.u32 %r7,%r2,1; add.u32 %r70,%r2,2; add.u32 %r71,%r2,3;\n"
	"setp.ge.u32 %p1,%r2,%r11; @%p1 bra $done;\n"
	"setp.ge.u32 %p4,%r7,%r11;\n"
	"selp.b32 %r7,%r2,%r7,%p4;\n"
	"setp.ge.u32 %p5,%r70,%r11;\n"
	"selp.b32 %r70,%r2,%r70,%p5;\n"
	"setp.ge.u32 %p6,%r71,%r11;\n"
	"selp.b32 %r71,%r2,%r71,%p6;\n"
	"shr.u32 %r33,%r1,2;\n"
	"and.b32 %r34,%r1,3;\n"
	"mul.lo.u32 %r4,%r2,%r12; shl.b32 %r4,%r4,4;\n"
	"shl.b32 %r5,%r33,4; shl.b32 %r6,%r34,2; add.u32 %r4,%r4,%r5; add.u32 %r4,%r4,%r6;\n"
	"cvt.u64.u32 %rd5,%r4; add.u64 %rd5,%rd5,%rd1;\n"
	"mul.lo.u32 %r4,%r7,%r12; shl.b32 %r4,%r4,4;\n"
	"shl.b32 %r5,%r33,4; shl.b32 %r6,%r34,2; add.u32 %r4,%r4,%r5; add.u32 %r4,%r4,%r6;\n"
	"cvt.u64.u32 %rd6,%r4; add.u64 %rd6,%rd6,%rd1;\n"
	"mul.lo.u32 %r4,%r70,%r12; shl.b32 %r4,%r4,4;\n"
	"shl.b32 %r5,%r33,4; shl.b32 %r6,%r34,2; add.u32 %r4,%r4,%r5; add.u32 %r4,%r4,%r6;\n"
	"cvt.u64.u32 %rd22,%r4; add.u64 %rd22,%rd22,%rd1;\n"
	"mul.lo.u32 %r4,%r71,%r12; shl.b32 %r4,%r4,4;\n"
	"shl.b32 %r5,%r33,4; shl.b32 %r6,%r34,2; add.u32 %r4,%r4,%r5; add.u32 %r4,%r4,%r6;\n"
	"cvt.u64.u32 %rd23,%r4; add.u64 %rd23,%rd23,%rd1;\n"
	"shl.b32 %r5,%r33,5; shl.b32 %r6,%r34,2; add.u32 %r5,%r5,%r6; add.u32 %r5,%r5,4;\n"
	"cvt.u64.u32 %rd17,%r5; add.u64 %rd17,%rd17,%rd3;\n"
	"mul.lo.u32 %r4,%r2,%r12; shl.b32 %r4,%r4,2; cvt.u64.u32 %rd18,%r4; add.u64 %rd18,%rd18,%rd2;\n"
	"mul.lo.u32 %r4,%r7,%r12; shl.b32 %r4,%r4,2; cvt.u64.u32 %rd21,%r4; add.u64 %rd21,%rd21,%rd2;\n"
