    pMemcpyDtoH = (CUresult (*)(void *, uint64_t, size_t))dlsym(libcuda, "cuMemcpyDtoH_v2");
    pMemcpyHtoD = dlsym(libcuda, "cuMemcpyHtoD_v2");
