/* Exp41 diagnostic mode switch (run #69). Q4_RING:
     0 = serial malloc staging + one sync H2D (the proven path, run #30)
     1 = pinned ring + cuMemcpyHtoDAsync (DMA/CPU overlap)
     2 = one big pinned staging buffer + one sync H2D (no async)
   Why this exists: h2dp3 measured repack+H2D 981 ms (pageable) vs 185 ms (pinned)
   on an idle board, but INSIDE the engine mode 1 measured 6352 ms. Hypothesis:
   on a 4 GB Tegra with the 714 MB blob mmap'd (mlock fails: errno 12) the repack's
   source reads come from page cache; pinning host memory and/or running the DMA
   concurrently evicts/starves those pages, so repack's 526 MB of source reads go to
   flash. Mode 2 separates "writing pinned pages" from "DMA running concurrently". */
#define Q4_RING 2

typedef struct {
    uint8_t *slot[Q4_NSLOT];  /* pinned slots (NULL = unallocated) */
    uint64_t slotfill;        /* bytes written into the current slot */
    int npend;                /* copies enqueued but not yet stream-synced */
    int pinned;               /* 1 = slots in use */
} q4ring;

static void q4_ring_fini(q4ring *R) {
    int i;
    for (i = 0; i < Q4_NSLOT; i++)
        if (R->slot[i]) {
            /* free() on a cuMemHostAlloc pointer is a double free (SIGSEGV seen in
               the run #69 probe at cuda_init+3396); hand it back to the driver and
               only fall back to free() when the driver rejects it. */
            if (!pMemFreeHost || pMemFreeHost(R->slot[i])) free(R->slot[i]);
            R->slot[i] = 0;
        }
