static int q4_ring_init(q4ring *R, size_t total) {
    int i;
    memset(R, 0, sizeof(*R));
    if (!pMemHostAlloc || !pMemFreeHost) return 0;
    for (i = 0; i < Q4_NSLOT; i++) {
        void *p = 0;
        if (pMemHostAlloc(&p, Q4_SLOT, 0)) {
            printf("q4_build: pin %d x %llu MB failed\n",
                   Q4_NSLOT, (unsigned long long)(Q4_SLOT >> 20));
            q4_ring_fini(R);
            return 0;
