        /* Pre-touch: first-touch faults on driver-pinned pages cost ~7 ms/MB
           (measured, run #69); the repack writes every byte, so it would pay them
           serially anyway - paying them here with a streaming memset is ~6x cheaper. */
        memset(p, 0, Q4_SLOT);
        R->slot[i] = (uint8_t *)p;
    }
